parameters.jsCode:
// >>> SETUP: change TIMEZONE to your own, e.g. 'America/New_York', 'Europe/London', 'Asia/Dubai' <<<
const TIMEZONE = 'America/New_York';

const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const nowMs = $now.toMillis();
const windowEndMs = nowMs + 45 * 60 * 1000;
const out = [];
for (const r of rows) {
  const sent = String(r.call_prep_sent || '').toLowerCase();
  if (sent === 'true') continue;
  const raw = r.call_at;
  if (!raw) continue;
  const ms = new Date(raw).getTime();
  if (isNaN(ms)) continue;
  if (ms < nowMs || ms > windowEndMs) continue;

  out.push({ json: {
    lead_id: r.lead_id,
    contact_name: r.contact_name || '',
    company: r.company || '',
    domain: r.domain || '',
    url: r.domain ? ('https://' + String(r.domain).replace(/^https?:\/\//i,'')) : '',
    notes: r.notes || '',
    research_brief: r.research_brief || '',
    chat_id: String(r.chat_id || ''),
    hasChat: !!(r.chat_id),
    callTimeLabel: $now.plus({ milliseconds: ms - nowMs }).setZone(TIMEZONE).toFormat('t'),
  }});
}
return out;

const item = $input.first().json;
const status = item.statusCode || 0;
const html = typeof item.body === 'string' ? item.body : '';
const ctx = $('Filter Call Window').item.json;

function pick(re){ const m = html.match(re); return m ? (m[1]||'').trim() : ''; }
const title = pick(/<title[^>]*>([\s\S]*?)<\/title>/i);
const metaDesc = pick(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i);
const h1s = (html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/gi) || [])
  .map(h => h.replace(/<[^>]+>/g,'').trim()).filter(Boolean).slice(0,5);
const hasBlog = /href=["'][^"']*\/blog/i.test(html);
const hasOnlineOrdering = /(order online|order now|add to cart|checkout|book (a )?table|reservation)/i.test(html);
const social = [];
if(/instagram\.com\//i.test(html)) social.push('instagram');
if(/facebook\.com\//i.test(html)) social.push('facebook');
if(/linkedin\.com\//i.test(html)) social.push('linkedin');

let text = html.replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ')
  .replace(/<[^>]+>/g,' ').replace(/&nbsp;/gi,' ').replace(/\s+/g,' ').trim();
const wordCount = text ? text.split(' ').length : 0;
const fetchOk = status >= 200 && status < 400 && html.length > 200;
const likelyJsRendered = fetchOk && wordCount < 60;

return [{ json: Object.assign({}, ctx, {
  title, metaDesc, h1s, hasBlog, hasOnlineOrdering,
  social, fetchOk, likelyJsRendered,
  textSample: text.slice(0, 2500),
}) }];

